def resolve(path, cwd, links):
    # Handle more than 8 links
    link_count = [0]

    def resolve_helper(current_path, remaining_components):
        # Process remaining components one by one
        for component in remaining_components:
            # Skip empty components and '.'
            if component == '' or component == '.':
                continue

            # Handle '..'
            if component == '..':
                # Move to parent, but '/' stays '/'
                if current_path != '/':
                    current_path = current_path.rsplit('/', 1)[0]
                    if current_path == '':
                        current_path = '/'
                continue

            # Append the component
            if current_path == '/':
                candidate = '/' + component
            else:
                candidate = current_path + '/' + component

            # Check if this path is a symlink
            if candidate in links:
                link_count[0] += 1
                if link_count[0] > 8:
                    return None

                # Get the link target
                target = links[candidate]

                # If target doesn't start with '/', it's relative to the directory containing the link
                if not target.startswith('/'):
                    # Directory containing the link is the parent of candidate
                    if candidate == '/':
                        link_dir = '/'
                    else:
                        link_dir = candidate.rsplit('/', 1)[0]
                        if link_dir == '':
                            link_dir = '/'

                    # Resolve target relative to link_dir
                    if link_dir == '/':
                        target = '/' + target
                    else:
                        target = link_dir + '/' + target

                # Parse target into components and resolve recursively
                if target.startswith('/'):
                    current_path = '/'
                    target_components = target[1:].split('/')
                else:
                    # This shouldn't happen after our processing, but handle it
                    target_components = target.split('/')

                result = resolve_helper(current_path, target_components)
                if result is None:
                    return None
                current_path = result
            else:
                current_path = candidate

        return current_path

    # Normalize the input path
    if path.startswith('/'):
        start_path = '/'
        path_components = path[1:].split('/')
    else:
        # Relative path - resolve relative to cwd
        start_path = cwd
        path_components = path.split('/')

    # Resolve the path
    result = resolve_helper(start_path, path_components)

    if result is None:
        return None

    # Remove trailing slash, except for '/'
    if result != '/' and result.endswith('/'):
        result = result.rstrip('/')

    return result

